fn batch_prefix_products(flat:&[M31])->(Vec<M31>,M31) {
    let mut prefixes=Vec::with_capacity(flat.len());
    let mut product=M31::ONE;
    let mut index=0;
    while index<flat.len() {
        let value=flat[index];
        prefixes.push(product);
        product=product.mul(value);
        index+=1;
    }
    (prefixes,product)
}

